            self.emit(f"{words} = OpBitcast %v2uint_d {result}")
            for index in range(2):
                word = self.tmp()
                self.emit(f"{word} = OpCompositeExtract %uint {words} {index}")
                self.dst({"k": "vgpr", "r": dst["r"] + index, "n": 1}, word)
