            if op == "s_pack_hh_b32_b16":
                self.emit(f"{lo} = OpShiftRightLogical %uint {x} {self.cu(16)}")
            else:
                self.emit(f"{lo} = OpBitwiseAnd %uint {x} {self.cu(0xFFFF)}")
