            self.emit(f"{lo} = OpLoad %uint %ud_code_lo_p")
            self.emit(f"{hi} = OpLoad %uint %ud_code_hi_p")
            self.emit(f"{s} = OpIAddCarry %umul {lo} {self.cu(nxt)}")
