            for src in a[1:3]:
                halves.append(self.saturate_int16(self.src_u(src), signed=(op == "v_cvt_pk_i16_i32")))
            sh, r = self.tmp(), self.tmp()
            self.emit(f"{sh} = OpShiftLeftLogical %uint {halves[1]} {self.cu(16)}")
            self.emit(f"{r} = OpBitwiseOr %uint {halves[0]} {sh}")
            self.dst(a[0], r)
